bool GeneratedProfilesMatch(const GeneratedUniversalProfile& left,
                            const GeneratedUniversalProfile& right) {
  return left.upper_family_mask == right.upper_family_mask &&
         left.lower_family_mask == right.lower_family_mask &&
         left.execute_count == right.execute_count &&
         left.continue_at_profile_exit == right.continue_at_profile_exit &&
         left.reachable_pairs == right.reachable_pairs;
}

