struct LoopKernelBundleCacheEntry {
  u64 identity = 0u;
  u64 last_use = 0u;
  u32 analysis_start_pc = 0u;
  u32 configuration_bits = 0u;
  // Direct-TFX geometry is part of executable ownership.  One VU program can
  // emit different packed GIF contracts on successive invocations (BSpline
  // alternates 24- and 120-vertex packets), so source/entry/profile alone is
  // not a sufficient cache key.
  std::array<u32, 4> gif_tag{};
  GeneratedLoopKernelBundle descriptor;
  GeneratedCgProgram compiler_program;
  struct RuntimePlan;
  std::shared_ptr<const RuntimePlan> runtime_plan;
  // ABI 26 remains immediately executable. Once GS observes a stable exact
  // variance set, one corrected partial-batch variant is generated
  // asynchronously and cached beside it; compilation can never suspend or
  // invalidate the base owner.
  GeneratedBatchVaryingLiveIns observed_batch_variance{};
  u32 batch_variance_observations = 0u;
  GeneratedLoopKernelBundle partial_batch_descriptor;
  GeneratedCgProgram partial_batch_compiler_program;
  std::shared_ptr<const GeneratedCgProgram> partial_batch_runtime_program;
  bool partial_batch_built = false;
  bool partial_batch_submitted = false;
  // Registration is a separate GS-owned stage. A queued key is not an
  // executable and must never leak into the lock-only hot selectors below.
  bool partial_batch_ready = false;
  bool partial_batch_failed = false;
  // A private ABI-26/33 canary is eligible only for bounded attestation. CPU
  // MTVU owns the interval until its ABI-43/44 no-write product is compiled
  // and registered. The product retains exact canary indexing/ownership, but
  // its pruned raster-only cone has no BUFFER2/BUFFER3 writable contract.
  GeneratedLoopKernelBundle product_descriptor;
  GeneratedCgProgram product_compiler_program;
  std::shared_ptr<const GeneratedCgProgram> product_runtime_program;
  bool product_built = false;
  bool product_submitted = false;
  // Set only after the registry has published the product GXP.  Dispatch
  // cost entries deliberately retain an executable hint, so submission alone
  // is insufficient: selecting a queued product here would turn an otherwise
  // executable canary into a transient CPU fallback.  Once ready, this bit
  // lets every source/output owner which generated the same lean root converge
  // without taking the program-registry mutex on every hot Execute.
  bool product_ready = false;
  bool product_failed = false;
  // Set by every state transition which may require one background pump.
  // Query paths may retry a rejected queue insertion without constructing Cg.
  bool pump_pending = false;
  bool submitted = false;
  bool failed = false;
  bool unavailable = false;
};

