BuildLoopKernelStoreDependencyPlan(const ParallelLoopKernel& kernel);

struct LoopKernelBundleCacheEntry::RuntimePlan {
  ParallelInvocationPlan invocation;
  GeneratedLoopKernelCandidateControlInputs compiler_control_inputs;
  GeneratedCgProgram generated;
  // Retain the bounded PairPlan CFG only for resumed entry-control preflight.
  // The hot SGX root still owns all VU arithmetic; this host replay evaluates
  // VI/control and immutable ILW/ILWR inputs only, before any GPU effect.
  // Output/tag/capacity variants of one exact source use identical PairPlans.
  // Share only that immutable source analysis, never live VI/memory inputs or
  // per-variant control proofs. Deferred owners retain it after cache eviction.
  std::shared_ptr<const ProgramAnalysis> control_analysis;
  // `closed_form_kernel` is the source-facing, parent-backedge-liveness
  // kernel which owns the cached GXP key and its private store journal.
  // `successor_kernel` is a complete runtime-only formula for architectural
  // VF/ACC/Q/P/I state after the final outer iteration.  Keeping these
  // separate prevents product commit from mistaking a legal JIT liveness
  // slice for a complete epoch state.
  ParallelLoopKernel closed_form_kernel;
  ParallelLoopKernel successor_kernel;
  // The architectural successor's expression topology is immutable for the
  // lifetime of this cached generated program. Compile its dependency walk
  // once here; hot Execute descriptors only capture changing leaf values.
  std::shared_ptr<const LoopKernelFinalDependencyPlan>
      successor_dependency_plan;
  std::shared_ptr<const LoopKernelFinalDependencyPlan>
      store_dependency_plan;
  ClosedFormNestedLoopProof closed_form;
  DirectTfxPostLoopProof post_loop;
  bool uses_closed_form_nested_loop = false;
};

struct NestedDirectBundleCacheEntry::RuntimePlan {
  FixedStructuredStateProgram fixed_state;
  ProgramAnalysis analysis;
  u32 parent_exit_block = 0u;
};

struct ColdPath1ReportHistory {
  struct Contract {
    std::array<u32, 4> tag{};
    u32 changes = 0u;
  };
  // Diagnostic budget only. Never evict a reported key and restart its flood;
  // excess distinct contracts share an explicitly marked sampled counter.
  std::array<Contract, 8> contracts{};
  u32 overflow_changes = 0u;
};

struct ColdPath1ReportDecision {
  u32 changes = 0u;
  bool emit = false;
  bool overflow = false;
};

ColdPath1ReportDecision AdvanceColdPath1ReportCounter(u32& changes,
                                                    bool overflow) {
  if (changes == std::numeric_limits<u32>::max())
    return {changes, false, overflow};
  ++changes;
  return {changes, changes <= 4u || (changes & (changes - 1u)) == 0u,
          overflow};
}

ColdPath1ReportDecision ObserveColdPath1Report(
    ColdPath1ReportHistory& history, const std::array<u32, 4>& tag) {
  for (auto& contract : history.contracts) {
    if (contract.changes == 0u) {
      contract.tag = tag;
      return AdvanceColdPath1ReportCounter(contract.changes, false);
    }
    if (contract.tag == tag)
      return AdvanceColdPath1ReportCounter(contract.changes, false);
  }
  return AdvanceColdPath1ReportCounter(history.overflow_changes, true);
}

