void ReportStructuredProfitabilityRejection(
    u32 pair_upper_bound, u32 transaction_pair_upper_bound,
    u32 fixed_firmware_jobs, u32 maximum_partition_jobs,
    std::size_t attempted_modules, const char* phase) {
  const u64 count = s_structured_bundle_profitability_rejections.fetch_add(
                        1u, std::memory_order_relaxed) +
                    1u;
  if (count > 8u && (count & (count - 1u)) != 0u)
    return;
  Console.WriteLn(
      "GPU-VU: structured generated candidate rejected before compiler: "
      "reason=firmware-job-budget pair_bound=%u transaction_pairs=%u "
      "fixed_jobs=%u generated_base_jobs=%u partition_budget=%u "
      "attempted_modules=%u phase=%s count=%llu; fixed universal ownership "
      "remains authoritative.",
      pair_upper_bound, transaction_pair_upper_bound, fixed_firmware_jobs,
      StructuredGeneratedFirmwareJobCount(0u, 0u),
      maximum_partition_jobs,
      static_cast<u32>(std::min<std::size_t>(
          attempted_modules, std::numeric_limits<u32>::max())),
      phase ? phase : "unknown", static_cast<unsigned long long>(count));
}

